1	/**
2	 * The canvas does no arithmetic on the map's numbers.
3	 *
4	 * Not one line of the files below adds a push, evaluates a shape, multiplies a
5	 * likelihood or averages anything. Every number drawn arrives from the server
6	 * and is carried, untouched and at full precision, to the moment it is printed.
7	 * The reason is not tidiness: the moment this half of the product works out a
8	 * number of its own there are two engines on the map, they disagree about half a
9	 * point, and nobody can say which is right.
10	 *
11	 * **Three things that are not arithmetic and are allowed by name.** Comparing a
12	 * push against a fixed threshold to pick a stroke width or a band of words.
13	 * Following arrows to find what is reachable. And working out where pixels go —
14	 * which is why the file that routes a wire around a tile is not on the list
15	 * below, and why its own tests are about geometry rather than about numbers.
16	 *
17	 * The check walks the syntax tree of each file rather than its text, so a
18	 * multiplication split over two lines, or hidden inside a template string, is
19	 * still found. It is the same technique the server uses to prove that nothing
20	 * anywhere averages two beliefs.
21	 */
22	
23	import ts from "typescript";
24	import { describe, expect, it } from "vitest";
25	
26	/**
27	 * Every file that touches one of the map's numbers and draws it.
28	 *
29	 * Deliberately not the whole tree: the file that works out where a wire goes
30	 * does nothing but pixel geometry, and pixel geometry is arithmetic on pixels.
31	 */
