34	  "/src/graph/wires/WireChip.tsx",
35	  "/src/graph/wires/CausalWire.tsx",
36	  "/src/graph/wires/lens.ts",
37	  "/src/components/Inspector.tsx",
38	  "/src/components/PathBar.tsx",
39	  "/src/components/OriginMark.tsx",
40	];
41	
42	/**
43	 * Every module in the tree, read as text by the build tool rather than off the
44	 * disk — so this test needs nothing but the browser types the rest of the app is
45	 * written against.
46	 */
47	const SOURCE = import.meta.glob("/src/**/*.{ts,tsx}", {
48	  query: "?raw",
49	  import: "default",
50	  eager: true,
51	}) as Record<string, string>;
52	
53	/**
54	 * The names a number off the map goes by.
55	 *
56	 * `p`, `lo` and `hi` are a likelihood and the range around it; `strength` is how
57	 * hard an arrow pushes; `prior` is the likelihood before an arrow's causes are
58	 * taken into account; `weight` is how much a piece of evidence counts. If an
59	 * expression combines two of anything, and either side reads one of these, the
60	 * canvas has started doing the engine's job.
61	 */
62	const A_NUMBER_OFF_THE_MAP = new Set([
63	  "p",
64	  "lo",
65	  "hi",
66	  "strength",
67	  "prior",
68	  "weight",
69	  "pathProduct",
70	  "conditional",
71	  "reading",
72	]);
73	
74	/** The four operators that would combine two numbers into a third. */
75	const COMBINES = new Set([
76	  ts.SyntaxKind.PlusToken,
77	  ts.SyntaxKind.MinusToken,
78	  ts.SyntaxKind.AsteriskToken,
79	  ts.SyntaxKind.SlashToken,
80	  ts.SyntaxKind.PlusEqualsToken,
81	  ts.SyntaxKind.MinusEqualsToken,
82	  ts.SyntaxKind.AsteriskEqualsToken,
83	  ts.SyntaxKind.SlashEqualsToken,
84	]);
85	
