87	function readsAMapNumber(node: ts.Node): boolean {
88	  let found = false;
89	  const look = (here: ts.Node): void => {
90	    if (ts.isPropertyAccessExpression(here) && A_NUMBER_OFF_THE_MAP.has(here.name.text)) {
91	      found = true;
92	    }
93	    if (ts.isIdentifier(here) && A_NUMBER_OFF_THE_MAP.has(here.text)) {
94	      found = true;
95	    }
96	    ts.forEachChild(here, look);
97	  };
98	  look(node);
99	  return found;
100	}
