1	/**
2	 * What a belief chip must never do.
3	 *
4	 * This is the one test in the browser half that holds the honesty rule up: two
5	 * significant figures, the range always, an absence with a reason rather than a
6	 * blank, and the word rather than a number when the reader has supposed a claim
7	 * true. It is the test decision record 0005 promised by name —
8	 * `test_chip_never_shows_more_than_two_significant_figures` is the first one
9	 * below — and every other test in this directory could pass while the product
10	 * still lied, if this one did not.
11	 */
12	
13	import { render, screen } from "@testing-library/react";
14	import { describe, expect, it } from "vitest";
15	import type { Slot } from "../../world";
16	import { BeliefChip, toReading, toTwoFigures } from "../BeliefChip";
17	
18	/**
19	 * Count the significant figures in a printed number.
20	 *
21	 * Every digit counts except the noughts in front: `.060` has two — the six and
22	 * the nought after it, which is there because we know the figure to that place
23	 * — and `.35` has two.
24	 */
25	function significantFigures(printed: string): number {
26	  return printed.replace(/[^0-9]/g, "").replace(/^0+/, "").length;
27	}
28	
29	/** The number a chip is showing. */
30	function readingOf(container: HTMLElement): string {
31	  return container.querySelector(".belief-chip__reading")?.textContent ?? "";
32	}
33	
34	/** The line under the number: the range, or the invitation to add your own. */
35	function underOf(container: HTMLElement): string {
36	  return container.querySelector(".belief-chip__under")?.textContent ?? "";
37	}
38	
39	/** A slot with a number in it. */
40	function known(p: number, lo: number, hi: number): Slot {
41	  return { reading: { p, lo, hi } };
42	}
43	
44	describe("a belief chip", () => {
45	  // The test decision record 0005 promised by name:
46	  // test_chip_never_shows_more_than_two_significant_figures
47	  it("never shows more than two significant figures", () => {
48	    // Deliberately awkward numbers: ones that round up into a shorter string,
49	    // ones with a nought that has to be kept, one that rounds to a whole number,
50	    // and the two ends of the range.
51	    const awkward: [number, number, number][] = [
52	      [0.3456789, 0.2222222, 0.4987654],
53	      [0.06123456, 0.0198765, 0.1444444],
54	      [0.999, 0.9512345, 0.99999],
55	      [0.5, 0.125, 0.875],
56	      [0.049999, 0.001234, 0.0987654],
57	    ];
58	
59	    for (const [p, lo, hi] of awkward) {
60	      const { container, unmount } = render(<BeliefChip owner="model" slot={known(p, lo, hi)} />);
61	      expect(significantFigures(readingOf(container))).toBeLessThanOrEqual(2);
62	      for (const end of underOf(container).split("–")) {
63	        expect(significantFigures(end)).toBeLessThanOrEqual(2);
64	      }
65	      unmount();
66	    }
67	  });
68	
69	  it("keeps the nought that carries information, rather than dropping it", () => {
70	    // Two significant figures means two digits that say something. Printing
71	    // `.06` for either of the first two would claim less precision than we have.
72	    expect(toTwoFigures(0.06)).toBe(".060");
73	    expect(toTwoFigures(0.0498)).toBe(".050");
74	    expect(toTwoFigures(0.06123)).toBe(".061");
75	    expect(toTwoFigures(0.35)).toBe(".35");
76	    expect(toReading(0.35, 0.22, 0.5)).toBe(".35 (.22–.50)");
77	  });
78	
79	  it("never omits the range", () => {
80	    const { container } = render(<BeliefChip owner="model" slot={known(0.61, 0.45, 0.74)} />);
81	    expect(readingOf(container)).toBe(".61");
82	    expect(underOf(container)).toBe(".45–.74");
83	    // And the whole reading, the way it would be read out loud, carries both.
84	    expect(screen.getByRole("button")).toHaveAttribute("aria-label", "model: .61 (.45–.74)");
85	  });
86	
87	  it("renders an absent number as an absence with its reason, never as a blank", () => {
88	    const { container } = render(
89	      <BeliefChip
90	        owner="market"
91	        slot={{
92	          absence: {
93	            kind: "no_market",
94	            words: "no market",
95	            reason: "No venue quotes this claim, so there is no price to read.",
96	          },
97	        }}
98	      />,
99	    );
100	
101	    expect(readingOf(container)).toBe("no market");
102	    expect(readingOf(container)).not.toBe("");
103	    // Nothing anywhere on the chip is a zero standing in for a number nobody has.
104	    expect(container.textContent).not.toMatch(/(^|[^.\d])0([^.\d]|$)/);
105	    expect(
106	      screen.getByText("No venue quotes this claim, so there is no price to read."),
107	    ).toBeInTheDocument();
108	  });
109	
110	  it("invites a number into the reader's own empty slot", () => {
111	    const { container } = render(
112	      <BeliefChip
113	        owner="user"
114	        slot={{
115	          absence: {
116	            kind: "not_said",
117	            words: "—",
118	            reason: "You have not put your own number on this yet.",
119	          },
120	        }}
121	      />,
122	    );
123	    expect(readingOf(container)).toBe("—");
124	    expect(underOf(container)).toBe("add yours");
125	  });
126	
127	  it("renders the word, not a likelihood, while a claim is supposed", () => {
128	    const { container } = render(
129	      <BeliefChip
130	        owner="model"
131	        slot={known(0.35, 0.22, 0.5)}
132	        standing={{
133	          words: "Supposed · Oct 1",
