1	/**
2	 * The path bar renders. It never multiplies.
3	 *
4	 * A chain of four plausible steps is not a plausible chain, and the number that
5	 * says what four steps come to together is the number the map exists to produce.
6	 * It arrives on the world, computed where the map's numbers are computed. If it
7	 * is absent the bar says so with its reason; it does not fall back to working
8	 * one out.
9	 */
10	
11	import { render, screen } from "@testing-library/react";
12	import { describe, expect, it } from "vitest";
13	import { aClaim, aWire, aWorld } from "../../test/aMap";
14	import type { WorldView } from "../../world";
15	import { bestBackedRoute, PathBar } from "../PathBar";
16	
17	/**
18	 * The stored example's own shape: the strait reaches the contract two ways, and
19	 * the producers are reachable only through the arrow that feeds back.
20	 */
21	function hormuzish(over: Partial<WorldView> = {}): WorldView {
22	  return aWorld({
23	    claims: ["H", "C", "B", "R", "M1"].map((id) =>
24	      aClaim({ id, kind: id === "H" ? "hypothesis" : "event" }),
25	    ),
26	    links: [
27	      aWire({ source: "H", target: "B", provenance: "argued" }),
28	      aWire({ source: "H", target: "C", provenance: "argued" }),
29	      aWire({ source: "C", target: "B", provenance: "argued" }),
30	      aWire({ source: "B", target: "M1", provenance: "argued" }),
31	      aWire({ source: "B", target: "R", provenance: "argued", reflexive: true }),
32	      aWire({ source: "R", target: "B", provenance: "argued" }),
33	    ],
34	    ...over,
35	  });
36	}
37	
38	describe("which route the bar shows", () => {
39	  it("test_the_best_backed_route_wins_and_a_tie_goes_to_the_shorter", () => {
40	    // The contract is reached by H → B → M1 and by H → C → B → M1. Every arrow
41	    // on both is argued, so their weakest arrows tie — and the tie goes to the
42	    // shorter.
43	    const found = bestBackedRoute(hormuzish(), "M1");
44	    expect(found.found).toBe(true);
45	    if (!found.found) {
46	      throw new Error("expected a route");
47	    }
48	    expect(found.route.steps.map((step) => step.claim.id)).toEqual(["B", "M1"]);
49	  });
50	
51	  it("test_a_better_backed_route_beats_a_shorter_one", () => {
52	    // Make the direct arrow the model merely asserting, and the long way round
53	    // becomes the better-backed route even though it takes an extra step.
54	    const world = hormuzish({
55	      links: [
56	        aWire({ source: "H", target: "B", provenance: "asserted" }),
57	        aWire({ source: "H", target: "C", provenance: "documented" }),
58	        aWire({ source: "C", target: "B", provenance: "documented" }),
59	        aWire({ source: "B", target: "M1", provenance: "documented" }),
60	      ],
61	    });
62	    const found = bestBackedRoute(world, "M1");
63	    if (!found.found) {
64	      throw new Error("expected a route");
65	    }
66	    expect(found.route.steps.map((step) => step.claim.id)).toEqual(["C", "B", "M1"]);
67	  });
68	
69	  it("test_a_route_never_walks_the_arrow_that_feeds_back", () => {
70	    // The producers are reached from the oil price only through the feedback
71	    // arrow. A chain's likelihood is read on the map with those set aside, so
72	    // there is no route here — and the bar says so in words.
73	    expect(bestBackedRoute(hormuzish(), "R")).toEqual({
74	      found: false,
75	      why: "nothing-reaches-it",
76	    });
77	  });
78	});
79	
80	describe("what the bar says", () => {
81	  it("test_renders_the_product_and_never_computes_one", () => {
82	    const world = hormuzish();
83	    const { container } = render(<PathBar world={world} claimId="M1" />);
84	
85	    // The route by name, and the absence where the number will go.
86	    expect(screen.getByText("H → B → M1")).toBeInTheDocument();
87	    expect(screen.getByText("no engine yet")).toBeInTheDocument();
88	    expect(screen.getByText(/Nothing has worked it out/)).toBeInTheDocument();
89	    // No number was invented to stand in for the missing one.
90	    expect(container.querySelector('[data-reading="number"]')).toBeNull();
91	
92	    // And when the world does carry one, the bar prints it as it was given.
93	    const withANumber = aWorld({
94	      ...world,
95	      claims: world.claims.map((claim) =>
96	        claim.id === "M1"
97	          ? aClaim({ ...claim, pathProduct: { reading: { p: 0.18, lo: 0.1, hi: 0.3 } } })
98	          : claim,
99	      ),
100	    });
101	    const second = render(<PathBar world={withANumber} claimId="M1" />);
102	    expect(second.container.querySelector('[data-reading="number"]')?.textContent).toBe(".18");
103	  });
104	
105	  it("test_tells_no_route_apart_from_no_number", () => {
106	    // Three readings, and they are never allowed to stand in for one another.
107	    const world = hormuzish();
108	
109	    const nothingSelected = render(<PathBar world={world} claimId={null} />);
110	    expect(
111	      nothingSelected.container.querySelector('[data-reading="no-path-shown"]')?.textContent,
112	    ).toBe("no path shown");
113	    nothingSelected.unmount();
114	
115	    const noRoute = render(<PathBar world={world} claimId="R" />);
116	    expect(noRoute.container.querySelector('[data-reading="no-route"]')?.textContent).toBe(
117	      "no path from the hypothesis reaches this claim any more",
118	    );
119	    noRoute.unmount();
120	
121	    const noNumber = render(<PathBar world={world} claimId="M1" />);
122	    expect(noNumber.container.querySelector('[data-reading="no-number"]')?.textContent).toBe(
123	      "no engine yet",
124	    );
125	  });
126	
127	  it("test_the_wart_is_said_out_loud_rather_than_hidden", () => {
128	    render(<PathBar world={hormuzish()} claimId="M1" />);
129	    expect(document.body.textContent).toContain("read on its own resolve-by day");
130	    expect(document.body.textContent).toContain(
131	      "it is not the chance of the whole chain happening together",
132	    );
133	  });
134	
135	  it("test_the_bar_never_disappears", () => {
